// Models/RepairGuide.swift
import Foundation

// Chain-of-Thought diagnosis result
struct DiagnosisResult {
    var brand: String
    var model: String
    var symptom: String
    var possibleFailures: [String]
    var verificationStep: String
    var confidenceScore: Double       // 0.0 – 1.0
    var isSafeToProcceed: Bool
    /// Pre-formed YouTube search query generated by the AI from brand + model + component + issue.
    /// Falls back to a client-side concatenation if the AI left it empty.
    var youtubeSearchQuery: String
    /// Human-readable device name returned by the server (e.g. "iPad Pro 12.9").
    /// Takes priority over brand+model join in the clarification message so the
    /// user sees the actual device name, not "unknown" or a category label.
    var detectedDevice: String?
    /// True when the backend is uncertain about the device model and needs the user to confirm.
    /// Triggers ModelConfirmationCard in RepairHubView before the repair plan is shown.
    var needsModelVerification: Bool
    /// The model name the AI guessed — displayed in ModelConfirmationCard.
    var suggestedModel: String?

    /// Best-effort fallback: build query from existing fields when AI didn't supply one.
    static func buildQuery(brand: String, model: String, symptom: String) -> String {
        let device = [brand, model].filter { !$0.isEmpty }.joined(separator: " ")
        let s = symptom.trimmingCharacters(in: .whitespaces)
        return device.isEmpty ? "How to fix \(s)" : "How to fix \(device) \(s)"
    }
}

struct RepairStep: Identifiable {
    let id: UUID
    var order: Int
    var title: String
    var detail: String
    var arAnchorDescription: String?  // hint for RealityKit placement
    var toolsRequired: [String]
    var warningNote: String?

    init(
        id: UUID = UUID(),
        order: Int,
        title: String,
        detail: String,
        arAnchorDescription: String? = nil,
        toolsRequired: [String] = [],
        warningNote: String? = nil
    ) {
        self.id                   = id
        self.order                = order
        self.title                = title
        self.detail               = detail
        self.arAnchorDescription  = arAnchorDescription
        self.toolsRequired        = toolsRequired
        self.warningNote          = warningNote
    }
}

struct RepairGuide: Identifiable {
    let id: UUID
    var session: RepairSession
    var diagnosis: DiagnosisResult?
    var steps: [RepairStep]
    var requiredParts: [RepairPart]
    /// Bounding boxes from Gemini Vision — used by ARRepairView for raycast-based placement.
    var partBoundingBoxes: [PartBoundingBox]

    init(
        id: UUID = UUID(),
        session: RepairSession,
        diagnosis: DiagnosisResult? = nil,
        steps: [RepairStep] = [],
        requiredParts: [RepairPart] = [],
        partBoundingBoxes: [PartBoundingBox] = []
    ) {
        self.id                = id
        self.session           = session
        self.diagnosis         = diagnosis
        self.steps             = steps
        self.requiredParts     = requiredParts
        self.partBoundingBoxes = partBoundingBoxes
    }
}

struct RepairPart: Identifiable {
    let id: UUID
    var name: String
    var partNumber: String
    var estimatedPrice: Double
    var buyURL: URL?
    var isAvailableLocally: Bool

    init(
        id: UUID = UUID(),
        name: String,
        partNumber: String,
        estimatedPrice: Double,
        buyURL: URL? = nil,
        isAvailableLocally: Bool = false
    ) {
        self.id                 = id
        self.name               = name
        self.partNumber         = partNumber
        self.estimatedPrice     = estimatedPrice
        self.buyURL             = buyURL
        self.isAvailableLocally = isAvailableLocally
    }
}
